/**
 * DNS on the box (compose profile `dns`): the sam-dns server (deploy/selfhost/sam-dns) answers
 * for SAM_DOMAIN once the operator delegates it (README "DNS on the box"). The deploy then:
 *
 * - tells the Worker to keep its DNS records in the box's own zone (`SAM_DNS_PROVIDER=box`,
 *   apps/api/src/selfhost/dns/), which sam-dns syncs from the loopback gateway route;
 * - renders `dns.env` for sam-dns and Caddy: the TSIG key Caddy signs its RFC 2136 updates with
 *   (a platform key, generated by `--init`, sealed with the others, rotated by
 *   `pnpm selfhost:secrets rotate dns-update-key`).
 *
 * The profile is refused without the box's public IPv4 (the glue record sam-dns serves) and with
 * a TLS mode that would still ask another DNS provider for the wildcard certificate: once the
 * zone is delegated to the box, a challenge written to Cloud DNS is invisible to Let's Encrypt.
 */
import { isIPv4 } from 'node:net';

import { composeProfileEnabled } from './mail-settings.js';

type Box = Readonly<Record<string, string>>;

export const DNS_PROFILE = 'dns';
export const DNS_ENV_FILE = 'dns.env';
export const DNS_TSIG_SECRET = 'SAM_DNS_TSIG_SECRET';
/** The TSIG key name Caddy and sam-dns share (FQDN, as RFC 8945 names keys). */
export const DNS_TSIG_KEY_NAME = 'sam-acme.';
/** TLS modes that work with the zone delegated to the box. */
const BOX_DNS_TLS_MODES = ['dns-rfc2136', 'internal'];

export function boxDnsEnabled(box: Box): boolean {
  return composeProfileEnabled(box, DNS_PROFILE);
}

/** Checks the box's DNS settings agree with each other; throws with the fix. */
export function assertBoxDnsSettings(box: Box): void {
  const tlsMode = box.SAM_TLS_MODE?.trim() ?? '';
  if (!boxDnsEnabled(box)) {
    if (tlsMode === 'dns-rfc2136') {
      throw new Error(
        `SAM_TLS_MODE=dns-rfc2136 asks the box's own DNS server for the certificate: add ` +
          `${DNS_PROFILE} to COMPOSE_PROFILES (README "DNS on the box")`
      );
    }
    return;
  }
  if (!isIPv4(box.SAM_DNS_PUBLIC_IPV4?.trim() ?? '')) {
    throw new Error(
      `the ${DNS_PROFILE} profile needs SAM_DNS_PUBLIC_IPV4, the box's public IPv4 address ` +
        '(the glue record in the parent zone points at it)'
    );
  }
  if (!BOX_DNS_TLS_MODES.includes(tlsMode)) {
    throw new Error(
      `the ${DNS_PROFILE} profile needs SAM_TLS_MODE=dns-rfc2136 (or internal for a local ` +
        `proof), not ${tlsMode || '(unset)'}: with SAM_DOMAIN delegated to the box, another DNS ` +
        "provider's challenge records are invisible to Let's Encrypt"
    );
  }
}

/** Worker vars for DNS on the box ({} when the profile is off: the Worker keeps calling Cloudflare). */
export function boxDnsWorkerVars(box: Box): Record<string, string> {
  assertBoxDnsSettings(box);
  return boxDnsEnabled(box) ? { SAM_DNS_PROVIDER: 'box' } : {};
}

/** The dotenv docker compose passes to sam-dns and Caddy (`env_file`). */
export function renderDnsEnv(tsigSecret: string): string {
  if (!/^[A-Za-z0-9+/]{43}=$/.test(tsigSecret)) {
    throw new Error(`${DNS_TSIG_SECRET} must be 32 bytes of base64`);
  }
  return `${DNS_TSIG_SECRET}=${tsigSecret}\nSAM_DNS_TSIG_KEY_NAME=${DNS_TSIG_KEY_NAME}\n`;
}
